<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue'; import { useRouter } from 'vue-router'; import { Copy, Plus, RefreshCcw, RotateCcw, Save, UserPlus } from '@lucide/vue'; import { api, type Brand, type WorkspaceRole } from '../lib/api'; import { useSessionStore } from '../stores/session'
const session=useSessionStore();const router=useRouter();const members=ref<Array<{id:string;email:string;displayName:string;role:WorkspaceRole;joinedAt:number}>>([]);const jobs=ref<Array<{id:string;postTitle:string;platform:string;status:string;attempt:number;errorMessage?:string}>>([]);const notice=ref('');const error=ref('');const inviteResult=ref('');const invite=reactive({email:'',role:'editor' as Exclude<WorkspaceRole,'owner'>});const brandForm=reactive({name:'',industry:'',audience:'',tone:'',keywords:'',bannedTerms:'',defaultCta:'',primaryColor:'#E9684A'})
function hydrate(brand:Brand|null){if(!brand)return;brandForm.name=brand.name;brandForm.industry=brand.industry;brandForm.audience=brand.audience;brandForm.tone=brand.tone;brandForm.keywords=parseList(brand.keywords).join('、');brandForm.bannedTerms=parseList(brand.bannedTerms).join('、');brandForm.defaultCta=brand.defaultCta;brandForm.primaryColor=brand.primaryColor}watch(()=>session.brand,hydrate,{immediate:true})
async function load(){[members.value,jobs.value]=await Promise.all([api.members(),api.publishJobs()])}
async function saveBrand(){try{await api.updateBrand(session.brandId,{...brandForm,keywords:split(brandForm.keywords),bannedTerms:split(brandForm.bannedTerms)});await session.loadBrands();notice.value='品牌設定已儲存'}catch(e){error.value=e instanceof Error?e.message:'儲存失敗'}}
async function sendInvite(){try{const result=await api.invite(invite.email,invite.role);inviteResult.value=`${location.origin}${result.invitePath}`;notice.value='邀請連結已建立'}catch(e){error.value=e instanceof Error?e.message:'建立邀請失敗'}}
async function copyInvite(){await navigator.clipboard.writeText(inviteResult.value);notice.value='邀請連結已複製'}
async function reset(){if(!confirm('確定重置目前工作空間的 Demo 情境資料？'))return;try{await api.resetDemo();notice.value='Demo 情境已重置';router.push('/overview')}catch(e){error.value=e instanceof Error?e.message:'重置失敗'}}
async function retry(id:string){try{await api.retryPublish(id);notice.value='已重新加入發布佇列';await load()}catch(e){error.value=e instanceof Error?e.message:'重試失敗'}}
async function runPublisher(){try{await api.runDemoPublisher();notice.value='已執行模擬發布排程器';await new Promise(r=>setTimeout(r,800));await load()}catch(e){error.value=e instanceof Error?e.message:'執行失敗'}}
function parseList(value:unknown){if(Array.isArray(value))return value;try{return JSON.parse(String(value))as string[]}catch{return String(value??'').split(/[、,，]/).filter(Boolean)}}function split(v:string){return v.split(/[、,，]/).map(i=>i.trim()).filter(Boolean)}onMounted(load)
</script>
<template><div class="page-stack"><section class="page-title-row"><div><p class="eyebrow">WORKSPACE SETTINGS</p><h2>設定</h2><p>管理品牌脈絡、團隊邀請與 Demo 營運資料。</p></div></section><p v-if="notice" class="notice">{{notice}}</p><p v-if="error" class="form-error banner">{{error}}</p><div class="settings-layout"><section class="panel settings-form"><div class="panel-head"><div><p class="eyebrow">BRAND PROFILE</p><h3>品牌 AI 脈絡</h3></div><button class="button primary" @click="saveBrand"><Save :size="16"/>儲存設定</button></div><div class="two-columns"><label>品牌名稱<input v-model="brandForm.name"></label><label>產業類型<input v-model="brandForm.industry" placeholder="生活選品、個人品牌…"></label></div><label>目標受眾<textarea v-model="brandForm.audience" rows="3"></textarea></label><label>品牌語氣<textarea v-model="brandForm.tone" rows="3"></textarea></label><div class="two-columns"><label>品牌關鍵字<input v-model="brandForm.keywords" placeholder="以頓號分隔"></label><label>禁用詞<input v-model="brandForm.bannedTerms" placeholder="以頓號分隔"></label></div><label>預設 CTA<input v-model="brandForm.defaultCta"></label><label>品牌主色<input v-model="brandForm.primaryColor" type="color"></label></section><section class="panel"><div class="panel-head"><div><p class="eyebrow">TEAM</p><h3>工作空間成員</h3></div><span>{{members.length}} 人</span></div><div class="member-list"><article v-for="item in members" :key="item.id"><span>{{item.displayName.slice(0,1)}}</span><div><strong>{{item.displayName}}</strong><small>{{item.email}}</small></div><i class="status-chip">{{item.role}}</i></article></div><form class="invite-form" @submit.prevent="sendInvite"><h4><UserPlus :size="17"/>邀請新成員</h4><input v-model="invite.email" type="email" required placeholder="member@example.com"><select v-model="invite.role"><option value="admin">管理員</option><option value="editor">編輯者</option><option value="reviewer">審核者</option><option value="viewer">檢視者</option></select><button class="button secondary"><Plus :size="15"/>建立邀請</button><div v-if="inviteResult" class="invite-link"><input :value="inviteResult" readonly><button type="button" @click="copyInvite"><Copy :size="15"/></button></div></form></section><section class="panel full-span"><div class="panel-head"><div><p class="eyebrow">PUBLISHING OPERATIONS</p><h3>模擬發布紀錄</h3></div><button class="button secondary" @click="runPublisher"><RefreshCcw :size="15"/>立即執行排程器</button></div><div class="publish-job-list"><article v-for="job in jobs" :key="job.id"><span class="platform-badge">{{job.platform}}</span><div><strong>{{job.postTitle}}</strong><small>{{job.errorMessage||`執行 ${job.attempt} 次`}}</small></div><i class="status-chip" :class="job.status">{{job.status}}</i><button v-if="job.status==='failed'" class="button secondary" @click="retry(job.id)"><RotateCcw :size="14"/>重試</button></article><p v-if="!jobs.length" class="muted">尚無發布工作</p></div></section><section class="panel full-span danger-panel"><div><p class="eyebrow">DEMO DATA</p><h3>重置展示情境</h3><p>清除目前工作空間的內容資料，重新建立審核、排程、發布與成效範例。</p></div><button class="button danger" @click="reset"><RotateCcw :size="16"/>重置 Demo</button></section></div></div></template>
